mcp_gateway {
  "server": "dbx",
  "tool": "dbx_execute_query",
  "arguments": {
    "connection_name": "新禅道",
    "sql": "SELECT id,status,assignedTo,openedBy,product,project,execution,resolution FROM zt_bug WHERE id=6337;"
  }
}
