    "sql": "UPDATE zt_bug SET status='resolved', resolution='fixed', resolvedBuild='trunk', resolvedBy='tiany', resolvedDate=NOW(), assignedTo='<openedBy>', lastEditedBy='tiany', lastEditedDate=NOW() WHERE id=6337;",
